PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS fpp_users (id TEXT PRIMARY KEY, external_oid TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, email TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS fpp_organizations (id TEXT PRIMARY KEY, name TEXT NOT NULL, locale TEXT NOT NULL, time_zone TEXT NOT NULL, buffer_days INTEGER NOT NULL, evidence_stale_hours INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS fpp_memberships (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, user_id TEXT NOT NULL, role TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(organization_id,user_id), FOREIGN KEY(organization_id) REFERENCES fpp_organizations(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES fpp_users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS fpp_workspaces (organization_id TEXT PRIMARY KEY, version INTEGER NOT NULL, workspace TEXT NOT NULL, updated_by TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(organization_id) REFERENCES fpp_organizations(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS fpp_sync_operations (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, user_id TEXT NOT NULL, idempotency_key TEXT NOT NULL, expected_version INTEGER NOT NULL, applied_version INTEGER NOT NULL, response TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(organization_id,idempotency_key), FOREIGN KEY(organization_id) REFERENCES fpp_organizations(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS fpp_audit_events (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, actor_user_id TEXT, action TEXT NOT NULL, object_type TEXT NOT NULL, object_id TEXT NOT NULL, summary TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(organization_id) REFERENCES fpp_organizations(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS fpp_technician_seats (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, membership_id TEXT NOT NULL UNIQUE, active_from TEXT NOT NULL, active_to TEXT, created_at TEXT NOT NULL, FOREIGN KEY(organization_id) REFERENCES fpp_organizations(id) ON DELETE CASCADE, FOREIGN KEY(membership_id) REFERENCES fpp_memberships(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS fpp_billing_accounts (organization_id TEXT PRIMARY KEY, external_customer_id TEXT, external_subscription_id TEXT, plan TEXT NOT NULL, seat_quantity INTEGER NOT NULL, state TEXT NOT NULL, period_end TEXT, last_event_id TEXT, updated_at TEXT NOT NULL, FOREIGN KEY(organization_id) REFERENCES fpp_organizations(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS fpp_billing_events (event_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, event_type TEXT NOT NULL, payload TEXT NOT NULL, received_at TEXT NOT NULL, FOREIGN KEY(organization_id) REFERENCES fpp_organizations(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS fpp_memberships_user_idx ON fpp_memberships(user_id,status);
CREATE INDEX IF NOT EXISTS fpp_sync_operations_org_created_idx ON fpp_sync_operations(organization_id,created_at);
CREATE INDEX IF NOT EXISTS fpp_audit_events_org_created_idx ON fpp_audit_events(organization_id,created_at);
